from lib import *
E, M, S, H = 'easy', 'medium', 'sufficient', 'hard'

def body(fs, b='box', surface='none'):
    return {"kind": "forces", "body": b, "surface": surface, "forces": [{"angle": a, "size": s, "label": l} for a, s, l in fs]}

def dyn(mx, step, lab):
    return {"kind": "scale", "instrument": "dynamometer", "min": 0, "max": mx, "step": step, "label": lab, "value": 'f', "unit": 'Н'}

